// Lottie reward animations for finished tasks, reward claims and boss-battle wins.
//
// The store fires `lh:celebrate` window events (store.celebrate(kind)); this
// service plays the matching Lottie animation in a click-through overlay.
// Animations live in public/lottie/<kind>.json (generated by
// scripts/generate_reward_lottie.mjs). To use a free LottieFiles animation
// instead, download its "Lottie JSON" over that file, or set
// VITE_LOTTIE_CONFETTI_URL / VITE_LOTTIE_TROPHY_URL / VITE_LOTTIE_COINS_URL to a
// JSON URL (for example a lottie.host link). Respects prefers-reduced-motion.

export const REWARD_ANIMATION_KINDS = ['confetti', 'coins', 'trophy'];
// Higher wins when two celebrations overlap (a battle win also submits a task).
const PRIORITY = { confetti: 1, coins: 2, trophy: 3 };
const SIZE = { confetti: 'min(92vw, 560px)', coins: 'min(70vw, 360px)', trophy: 'min(70vw, 360px)' };

let lottiePromise = null;
let active = null; // { kind, anim, el, timer }

function env(name) {
  return (typeof import.meta !== 'undefined' && import.meta.env?.[name]) || '';
}

export function rewardAnimationUrl(kind) {
  const override = env(`VITE_LOTTIE_${String(kind).toUpperCase()}_URL`);
  if (override && /^https:\/\//i.test(override)) return override;
  const base = env('BASE_URL') || '/';
  return `${base.replace(/\/?$/, '/')}lottie/${kind}.json`;
}

function prefersReducedMotion() {
  try {
    return typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches === true;
  } catch {
    return false;
  }
}

function loadLottie() {
  if (!lottiePromise) {
    // The "light" SVG-only player (~150 KB) is all these animations need.
    lottiePromise = import('lottie-web/build/player/esm/lottie_light.min.js').then(m => m.default || m);
  }
  return lottiePromise;
}

function stopActive() {
  if (!active) return;
  clearTimeout(active.timer);
  try { active.anim?.destroy(); } catch { /* already gone */ }
  active.el?.remove();
  active = null;
}

export async function playRewardAnimation(kind = 'confetti') {
  if (!REWARD_ANIMATION_KINDS.includes(kind)) kind = 'confetti';
  if (typeof document === 'undefined' || !document.body || prefersReducedMotion()) return false;
  if (active && PRIORITY[active.kind] > PRIORITY[kind]) return false;
  stopActive();

  const el = document.createElement('div');
  el.className = 'lh-reward-lottie';
  el.setAttribute('aria-hidden', 'true');
  el.style.cssText = `position:fixed;left:50%;top:45%;transform:translate(-50%,-50%);width:${SIZE[kind]};aspect-ratio:1/1;pointer-events:none;z-index:90;`;
  document.body.appendChild(el);
  const mine = { kind, el, anim: null, timer: setTimeout(() => active === mine && stopActive(), 6000) };
  active = mine;

  try {
    const lottie = await loadLottie();
    if (active !== mine) return false; // replaced while the player was loading
    mine.anim = lottie.loadAnimation({
      container: el,
      renderer: 'svg',
      loop: false,
      autoplay: true,
      path: rewardAnimationUrl(kind)
    });
    mine.anim.addEventListener('complete', () => active === mine && stopActive());
    mine.anim.addEventListener('data_failed', () => active === mine && stopActive());
    return true;
  } catch (err) {
    console.warn('[RewardAnimation] Could not play', kind, err);
    if (active === mine) stopActive();
    return false;
  }
}

export function initRewardAnimations() {
  if (typeof window === 'undefined' || window.__lhRewardAnimationsReady) return;
  window.__lhRewardAnimationsReady = true;
  window.addEventListener('lh:celebrate', e => {
    playRewardAnimation(e?.detail?.kind);
  });
}
